const groqResponse = $input.first().json;
// Recuperamos los datos del nodo anterior
// IMPORTANTE: Asegúrate de que el nodo anterior se llama "Necesita IA?" 
// Si da error, cambia $('Necesita IA?') por $input.first().pairedItem.item.json
let prevData = {};
try {
   prevData = $('Necesita IA?').first().json;
} catch(e) {
   // Fallback por si acaso
   prevData = { title: "Sin Título" }; 
}

let datosIA = {};

try {
  const content = groqResponse.choices?.[0]?.message?.content || '{}';
  // Limpieza de seguridad por si la IA mete markdown
  const jsonString = content.replace(/```json\n?|```/g, '').trim();
  datosIA = JSON.parse(jsonString);
} catch (e) {
  // Si falla el parseo, datosIA se queda vacío
}

// 1. GESTIÓN DEL NOMBRE LIMPIO (La Joya de la Corona) 👑
// Si la IA nos dio el nombre, lo usamos. Si no, usamos el título original de Maps.
let nombreFinal = datosIA.nombre_limpio || prevData.title;

// Limpieza extra por si acaso devuelve "null" string
if (!nombreFinal || nombreFinal === 'null') {
    nombreFinal = prevData.title;
}

// 2. Gestión del Email
let emailIA = null;
if (datosIA.email_principal && datosIA.email_principal !== 'null' && datosIA.email_principal.includes('@')) {
   emailIA = datosIA.email_principal.toLowerCase().trim();
}

return {
  ...prevData,

  // AQUÍ GUARDAMOS EL TESORO
  nombre_limpio: nombreFinal,

  // Resto de datos actualizados
  email_principal: emailIA || prevData.email_principal,
  emails: datosIA.emails || prevData.emails,
  nombre_responsable: datosIA.nombre_responsable || prevData.nombre_responsable,
  telefono_movil: datosIA.telefono_movil || null,
  linkedin: datosIA.linkedin || prevData.linkedin,
  facebook: datosIA.facebook || prevData.facebook,
  instagram: datosIA.instagram || prevData.instagram,

  fuente_email: emailIA ? 'IA (Groq)' : 'Regex',
  necesita_ia: false
};

