// 1. Recuperamos la respuesta de la IA
const aiResponse = $input.first().json.choices?.[0]?.message?.content || "";

// 2. RECUPERACIÓN SEGURA DE DATOS (EL FIX) 🛠️
// En lugar de pairedItem, leemos directamente el nodo del Bucle.
// Asegúrate de que tu nodo SplitInBatches se llame exactamente: "Bucle Principal (1 a 1)"
let itemOriginal = {};

try {
    // Intentamos leer del bucle (lo más seguro)
    itemOriginal = $('Bucle Principal (1 a 1)').first().json;
} catch (e) {
    // Si falla (por cambio de nombre), intentamos pairedItem
    try {
        itemOriginal = $input.first().pairedItem.item.json;
    } catch (e2) {
        // Si todo falla, creamos un objeto vacío para que NO explote el error rojo
        itemOriginal = { title: "Clínica (Error Recuperación)" };
    }
}

// 3. Procesar el Nombre Limpio
// Usamos el título original como base (fallback)
let nombreFinal = itemOriginal.title || "Clínica"; 

try {
  if (aiResponse) {
     // Limpieza previa por si la IA mete texto antes del JSON
     const jsonString = aiResponse.substring(
         aiResponse.indexOf('{'), 
         aiResponse.lastIndexOf('}') + 1
     );

     const parsed = JSON.parse(jsonString);

     // Si la IA nos dio un nombre válido, lo usamos
     if (parsed.nombre_limpio && parsed.nombre_limpio.length > 2) {
         nombreFinal = parsed.nombre_limpio;
     }
  }
} catch (e) {
  // Si la IA devuelve basura, nos quedamos con el original y no rompemos nada
}

// 4. Salida fusionada
return {
  ...itemOriginal, // Mantenemos todos los datos viejos (email, web, etc)
  nombre_limpio: nombreFinal // Sobrescribimos/Creamos el nombre limpio
};

const items = $input.all();
const validItems = [];

for (const item of items) {
  const email = item.json.email_principal;

  // Validar que el email existe, no es "None" y tiene formato válido
  if (email && 
      email !== 'None' && 
      email !== 'none' && 
      email !== '' && 
      email.includes('@') &&
      !email.includes('example.com')) {
    validItems.push(item);
  }
}

// Limitar a 25 emails máximo por ejecución
const maxEmails = 40;
const limitedItems = validItems.slice(0, maxEmails);

console.log(`Total válidos: ${validItems.length}, Enviando: ${limitedItems.length}`);

return limitedItems;
